// passage of the site's full translation first, then one question on it, with
// four choices (as in the Engels Ludwig Feuerbach course). Korean passages are
// verbatim from the document marx-value-price-profit (scripts/check-course-source-excerpts.js
// checks them and their anchors). Marx gave the address in English, so the English passages are
// quoted from the 1898 English text the document carries.
// A passage may skip text with ' … '.
// Rewritten 2026-10-31 from the earlier quiz course that read this text together with the Critique of the Gotha Programme; the Gotha part is now its own course (marx-gotha-critique). Course and chapter ids stay so links keep working. Every question is new, so the lessons take new ids
// (wages-programme-chNN-reading) and old quiz answer history is not counted for them.

function t(ko, en) {
    return { ko, en };
}

const DOC = '/commulingo/docs/marx-value-price-profit';
const TITLE_KO = '『임금, 가격, 이윤』';
const TITLE_EN = 'Value, Price and Profit';

const LABELS = {
    'preliminary': t(`${TITLE_KO} 머리말`, `${TITLE_EN}, preliminary`),
    'section-1': t(`${TITLE_KO} 제1절`, `${TITLE_EN}, section I`),
    'section-2': t(`${TITLE_KO} 제2절`, `${TITLE_EN}, section II`),
    'section-3': t(`${TITLE_KO} 제3절`, `${TITLE_EN}, section III`),
    'section-4': t(`${TITLE_KO} 제4절`, `${TITLE_EN}, section IV`),
    'section-5': t(`${TITLE_KO} 제5절`, `${TITLE_EN}, section V`),
    'section-6': t(`${TITLE_KO} 제6절`, `${TITLE_EN}, section VI`),
    'section-7': t(`${TITLE_KO} 제7절`, `${TITLE_EN}, section VII`),
    'section-8': t(`${TITLE_KO} 제8절`, `${TITLE_EN}, section VIII`),
    'section-9': t(`${TITLE_KO} 제9절`, `${TITLE_EN}, section IX`),
    'section-10': t(`${TITLE_KO} 제10절`, `${TITLE_EN}, section X`),
    'section-11': t(`${TITLE_KO} 제11절`, `${TITLE_EN}, section XI`),
    'section-12': t(`${TITLE_KO} 제12절`, `${TITLE_EN}, section XII`),
    'section-13': t(`${TITLE_KO} 제13절`, `${TITLE_EN}, section XIII`),
    'section-14': t(`${TITLE_KO} 제14절`, `${TITLE_EN}, section XIV`),
};

function passage(anchor, contextKo, contextEn, quoteKo, quoteEn) {
    return {
        context: t(contextKo, contextEn),
        source: { href: `${DOC}#${anchor}`, label: LABELS[anchor], quote: t(quoteKo, quoteEn) },
    };
}

// Choices and their feedback are authored correct answer first, which is how
// they are stored (answer 0); the player shuffles them for display.
function q(where, koPrompt, enPrompt, koChoices, enChoices, koExplanation, enExplanation, koFeedback, enFeedback) {
    return {
        type: 'multiple_choice',
        points: 0,
        context: where.context,
        prompt: t(koPrompt, enPrompt),
        choices: { ko: koChoices, en: enChoices },
        answer: 0,
        explanation: t(koExplanation, enExplanation),
        choiceFeedback: { ko: koFeedback, en: enFeedback },
        source: where.source,
    };
}

function chapter(ch, anchor, titleKo, titleEn, summaryKo, summaryEn, questions) {
    const id = `wages-programme-ch${String(ch).padStart(2, '0')}`;
    return {
        id,
        volumeNumber: 0,
        chapterNumber: ch,
        title: t(titleKo, titleEn),
        sourceUrl: `${DOC}#${anchor}`,
        summary: t(summaryKo, summaryEn),
        lessons: [{
            id: `${id}-reading`,
            level: 'basic',
            title: t(titleKo, titleEn),
            questions: questions.map((item, index) => ({ ...item, id: `q${index + 1}`, points: 2 })),
        }],
    };
}

